# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
M, K, O, P, C, F = "Matteo", "Kim", "Signora Oh", "Park", "Chiara", "Filippo"
D = [
("#", "Scena 1 — Lunedì 28 aprile, ore 9.50. Gaon Department Store, ottavo piano. La sala d'attesa degli uffici acquisti.", "장면 1 — 4월 28일 월요일 오전 9시 50분. 가온백화점 8층. 구매 사무실 대기실."),
(None, "Un corridoio silenzioso, moquette grigia, una fila di sedie. Sul muro, i loghi dei marchi che il grande magazzino distribuisce. In fondo, una parete vuota. Matteo è seduto con la cartellina sulle ginocchia. Arriva Park con due bicchieri di carta.", "조용한 복도, 회색 카펫, 의자 한 줄. 벽에는 백화점이 취급하는 브랜드 로고들이 붙어 있다. 맨 끝은 빈 벽이다. 마테오가 서류철을 무릎에 올려놓고 앉아 있다. 지훈이 종이컵 두 개를 들고 온다."),
(P, "Caffè americano, signor Matteo. Al piano terra il caffè è migliore, ma ci vogliono dieci minuti di ascensore.", "아메리카노예요, 마테오 씨. 1층 커피가 더 맛있는데, 엘리베이터 타는 데만 10분 걸려요."),
(M, "Grazie, Ji-hoon. Lei non dovrebbe essere giù, al pop-up?", "고마워요, 지훈 씨. 1층 팝업에 있어야 하는 거 아니에요?"),
(P, "Apriamo alle dieci e mezza. Su-a è già lì: sta rifacendo la vetrina per la terza volta.", "10시 반에 열어요. 수아 씨가 벌써 내려가 있어요. 쇼윈도를 세 번째로 다시 꾸미는 중이에요."),
(M, "Ji-hoon, posso chiederLe una cosa da ex collega? Quella parete vuota, in fondo. È per un marchio nuovo?", "지훈 씨, 전 동료로서 하나 물어봐도 돼요? 저 끝의 빈 벽이요. 새 브랜드 자리예요?"),
(P, "(abbassa la voce) Si dice che sia per un marchio italiano. Ma io non so niente. Io porto solo il caffè.", "(목소리를 낮추며) 이탈리아 브랜드 자리라는 얘기가 있어요. 근데 전 아무것도 몰라요. 커피만 나르는걸요."),
(M, "Un marchio italiano. Grande o piccolo?", "이탈리아 브랜드라. 큰 데요, 작은 데요?"),
(P, "Non so niente, signor Matteo. Ma la signora Kim, da giovedì, entra in ufficio con il vostro catalogo sotto il braccio.", "아무것도 모른다니까요, 마테오 씨. 그런데 김 차장님이 목요일부터 여러분 카탈로그를 옆구리에 끼고 출근하세요."),
(M, "Sotto il braccio. È un buon segno o un cattivo segno?", "옆구리에요. 좋은 신호예요, 나쁜 신호예요?"),
(P, "Da noi si dice: quando la signora Kim porta un catalogo, il fornitore deve portare la penna.", "저희끼리 하는 말이 있어요. 김 차장님이 카탈로그를 들고 다니면 공급업체는 펜을 챙겨야 한대요."),
(None, "Una porta si apre. Esce una giovane donna in tailleur blu con un tablet.", "문이 열린다. 파란 정장 차림의 젊은 여성이 태블릿을 들고 나온다."),
(O, "Signor Corsini? Sono Oh Ye-jin, assistente della signora Kim. Prego, da questa parte.", "코르시니 씨? 김 차장님 보좌 오예진입니다. 이쪽으로 오세요."),
(M, "Piacere. Lei parla italiano?", "반갑습니다. 이탈리아어 하세요?"),
(O, "Un anno a Perugia, all'Università per Stranieri. Abbastanza per tradurre i contratti. Non abbastanza per scherzare.", "페루자 외국인대학에서 1년 했어요. 계약서 번역할 정도는 돼요. 농담할 정도는 안 되고요."),
(M, "Allora oggi non scherzeremo.", "그럼 오늘은 농담하지 않겠습니다."),
(O, "Lo sa già, vedo.", "이미 아시네요."),

("#", "Scena 2 — Ore 10.00. L'ufficio di Kim Seo-yeon.", "장면 2 — 오전 10시. 김서연의 사무실."),
(None, "Un ufficio piccolo e ordinato. Sulla scrivania, il lookbook con le mani di Renzo in copertina, pieno di post-it gialli. Alla parete, una foto di Kim giovane davanti a Ponte Vecchio.", "작고 정돈된 사무실. 책상 위에 렌초의 손이 표지인 룩북이 노란 포스트잇으로 가득하다. 벽에는 폰테 베키오 앞에서 찍은 젊은 김서연의 사진."),
(K, "Buongiorno, Matteo. Si sieda. Ha dormito?", "안녕하세요, 마테오 씨. 앉으세요. 주무셨어요?"),
(M, "Quattro ore. Sua sorella... cioè, mia sorella mi ha raccontato la signora Yoon fino all'una.", "네 시간이요. 김서연 씨 누님이… 아니, 제 누나가 윤 여사 얘기를 새벽 1시까지 했어요."),
(K, "(ride) Si vede che è stanco: confonde le sorelle. Le dico subito perché l'ho chiamata da solo.", "(웃으며) 피곤하신 게 보이네요. 누나를 헷갈리시고. 왜 혼자 오시라고 했는지 바로 말씀드릴게요."),
(M, "La ascolto.", "듣고 있습니다."),
(K, "Perché con Sua sorella parlerei di borse. Con Lei devo parlare di soldi. E di paura.", "누님하고는 가방 얘기를 하게 되니까요. 마테오 씨하고는 돈 얘기를 해야 해요. 그리고 두려움 얘기도요."),
(M, "Di paura?", "두려움이요?"),
(K, "La mia. A Milano abbiamo parlato di dodici mesi, solo grandi magazzini di Seul. Dopo quattro giorni, ho tre problemi.", "제 두려움이요. 밀라노에선 12개월, 서울 백화점만이라고 얘기했죠. 나흘이 지나니 문제가 세 가지 생겼어요."),
(M, "Tre problemi in quattro giorni. Mi dica il primo.", "나흘에 문제 세 가지라. 첫 번째부터 말씀하세요."),
(K, "Il primo: Busan. Il pop-up l'hanno visto anche i grandi magazzini di Busan e di Daegu. Due colleghi mi hanno già chiesto il vostro contatto.", "첫째, 부산이요. 부산하고 대구 백화점들도 팝업을 봤어요. 동료 두 명이 벌써 연락처를 물어 왔어요."),
(M, "E Lei che cosa ha risposto?", "그래서 뭐라고 하셨어요?"),
(K, "Che il contatto ce l'ho io. Ma « Seul » non basta più. Voglio la Corea.", "연락처는 제가 갖고 있다고요. 하지만 '서울'로는 이제 부족해요. 저는 한국을 원해요."),
(M, "Il secondo?", "두 번째는요?"),
(K, "Internet. La signora Yoon, sabato, prima di comprare, ha cercato il vostro sito sul telefono. Ha controllato il prezzo in euro. Lo fanno tutte.", "인터넷이요. 윤 여사님도 토요일에 사기 전에 휴대폰으로 사이트를 찾아봤어요. 유로 가격을 확인했죠. 다들 그래요."),
(M, "E il prezzo era coerente. Seicentonovanta euro in Italia, un milione centonovantamila qui, con dazio, IVA e tutto il resto.", "그리고 가격은 맞았죠. 이탈리아에서 690유로, 여기선 관세랑 부가세 다 포함해서 119만 원."),
(K, "Oggi sì. Ma se un giorno il Suo sito fa uno sconto del venti per cento per il Black Friday, la mia cliente lo vede in tre secondi. E io resto con le borse sugli scaffali.", "오늘은요. 하지만 언젠가 마테오 씨 사이트가 블랙프라이데이에 20% 할인을 하면, 제 고객은 3초 만에 봐요. 그럼 가방은 제 선반에 남고요."),
(M, "E il terzo problema?", "세 번째 문제는요?"),
(K, "Il terzo sono io. Se investo in marketing, in vetrine, in personale che impara le frasi in italiano, voglio sapere che fra un anno il vostro marchio non lo vende anche il negozio dall'altra parte della strada.", "세 번째는 저예요. 제가 마케팅에, 쇼윈도에, 이탈리아어 문장 외우는 직원에게 투자한다면, 1년 뒤에 길 건너편 가게도 여러분 브랜드를 팔지 않을 거라는 걸 알아야 해요."),
(M, "Quindi, in concreto, che cosa propone?", "그래서 구체적으로 뭘 제안하시는 거예요?"),
(K, "(gira il tablet verso di lui) Esclusiva per tutta la Corea, tre anni. Tutti i canali: grandi magazzini, negozi, internet. Il Suo sito, in Corea, non vende. Rimanda a noi.", "(태블릿을 그에게 돌리며) 한국 전역 독점, 3년. 모든 채널이요. 백화점, 매장, 인터넷. 마테오 씨 사이트는 한국에서 판매하지 않고, 저희 쪽으로 연결해요."),
(None, "Matteo legge in silenzio. Prende un sorso di caffè, ormai freddo.", "마테오가 말없이 읽는다. 이미 식어 버린 커피를 한 모금 마신다."),
(M, "Kim, posso essere sincero?", "김서연 씨, 솔직하게 말해도 될까요?"),
(K, "Per questo l'ho chiamata da solo.", "그러려고 혼자 오시라고 한 거예요."),
(M, "Il sito non lo chiudo. Né in Corea né altrove. A meno che non mi dia una ragione che oggi non vedo.", "사이트는 안 닫아요. 한국에서도, 다른 데서도요. 오늘 제가 보지 못하는 이유를 주시지 않는 한은요."),
(K, "La ragione gliel'ho data: il prezzo.", "이유는 말씀드렸잖아요. 가격이요."),
(M, "Il prezzo è un problema di sconti, non di siti. Se il problema è lo sconto, togliamo lo sconto. Non il sito.", "가격은 할인의 문제지, 사이트의 문제가 아니에요. 문제가 할인이면 할인을 없애죠. 사이트 말고요."),
(K, "Mi spieghi meglio.", "더 자세히 말씀해 보세요."),
(M, "Il nostro sito, in Corea, vende allo stesso prezzo dei Suoi negozi. Mai uno sconto. Mai un Black Friday. E se un giorno lo facessimo, Lei avrebbe il diritto di rimandarci indietro le borse invendute.", "저희 사이트는 한국에서 백화점과 같은 가격으로 팔아요. 할인은 절대 없어요. 블랙프라이데이도 없고요. 만약 언젠가 그렇게 하면, 안 팔린 가방을 저희한테 돌려보낼 권리를 드리죠."),
(K, "Restituzione dell'invenduto nel caso in cui violiate il prezzo. Interessante. E perché il sito Le è così caro?", "가격 약속을 어기면 미판매분 반품. 흥미롭네요. 그런데 왜 그렇게 사이트를 아끼세요?"),
(M, "Perché è l'unico posto dove parliamo noi. Nei Suoi negozi parla Ji-hoon, e parla benissimo. Ma sul sito c'è la voce di mia sorella. Il marchio è ancora piccolo, Kim. Se gli togliamo la voce, diventa un'etichetta.", "저희가 직접 말하는 유일한 곳이니까요. 백화점에선 지훈 씨가 말하죠. 아주 잘하고요. 하지만 사이트에는 제 누나의 목소리가 있어요. 브랜드는 아직 작아요, 김서연 씨. 목소리를 빼면 그냥 라벨이 돼요."),
(K, "(lo guarda a lungo) Lei parla come un venditore. Ma ragiona come un fratello.", "(그를 한참 바라보며) 장사꾼처럼 말하시는데, 생각은 동생처럼 하시네요."),
(M, "In questa famiglia è difficile fare l'uno senza l'altro.", "저희 집안에선 둘 중 하나만 하기가 어려워요."),
(K, "Lo vedo. Anche nella mia. Mio padre ha un negozio di stoffe a Jongno, e mio fratello vende le stesse stoffe online. Litigano a ogni Chuseok.", "알아요. 저희 집도 그래요. 아버지는 종로에서 원단 가게를 하시고, 남동생은 같은 원단을 온라인으로 팔아요. 추석마다 싸우죠."),
(M, "Allora capisce perché il sito non lo chiudo.", "그럼 제가 왜 사이트를 안 닫는지 아시겠네요."),
(K, "E i grandi magazzini? Busan, Daegu?", "그럼 백화점은요? 부산, 대구는요?"),
(M, "Lì Le do ragione. Esclusiva per tutti i grandi magazzini coreani. Non solo Seul.", "그건 김서연 씨 말이 맞아요. 한국 모든 백화점 독점. 서울만이 아니라요."),
(K, "Tre anni.", "3년."),
(M, "Due. Piuttosto che promettere tre anni e litigare al secondo, preferisco firmarne due e rinnovare con piacere.", "2년이요. 3년을 약속하고 2년째에 싸우느니, 2년을 서명하고 기쁘게 갱신하는 게 나아요."),
(K, "Due anni, con una condizione mia: un minimo d'acquisto lo voglio scrivere io. Non per obbligarvi. Per obbligare me.", "2년. 제 조건 하나랑 같이요. 최소 구매량은 제가 적겠어요. 여러분을 묶으려는 게 아니라 저를 묶으려고요."),
(M, "Per obbligare Lei?", "김서연 씨를 묶으려고요?"),
(K, "Se scrivo un numero, il mio direttore mi dà il budget per arrivarci. Se non lo scrivo, il budget va al marchio francese del sesto piano.", "제가 숫자를 적으면 부장님이 거기 도달할 예산을 줘요. 안 적으면 예산은 6층 프랑스 브랜드로 가요."),
(M, "Allora scriva un numero bello alto.", "그럼 아주 높은 숫자를 적으세요."),
(K, "Lo scrivo giovedì della seconda settimana, quando so quanto abbiamo venduto. Glielo dico adesso: ci sto pensando.", "둘째 주 목요일에 적을게요. 얼마나 팔았는지 알게 되면요. 지금 말씀드리면, 생각 중이에요."),
(O, "(dalla porta) Signora Kim, il direttore la aspetta alle undici.", "(문가에서) 김 차장님, 부장님이 11시에 기다리세요."),
(K, "Arrivo. Matteo, pranzi pure. Ci vediamo alle due. Oh Ye-jin intanto scrive una bozza con quello che abbiamo detto.", "갈게요. 마테오 씨, 점심 드세요. 2시에 봬요. 그동안 오예진 씨가 우리가 말한 걸로 초안을 쓸 거예요."),

("#", "Scena 3 — Ore 14.05. L'ufficio di Kim.", "장면 3 — 오후 2시 5분. 김서연의 사무실."),
(None, "Sulla scrivania, un foglio di due pagine in coreano con la traduzione italiana a fronte, scritta da Oh Ye-jin. Matteo ha pranzato da solo in un piccolo locale di zuppe, dietro il grande magazzino, come faceva tre anni fa.", "책상 위에 오예진이 쓴 두 쪽짜리 한국어 문서가 있고, 맞은편에 이탈리아어 번역이 붙어 있다. 마테오는 백화점 뒤 작은 국밥집에서 혼자 점심을 먹었다. 3년 전처럼."),
(M, "Mi scusi, cinque minuti di ritardo. L'ascensore del pranzo.", "죄송해요, 5분 늦었어요. 점심시간 엘리베이터 때문에요."),
(K, "Dove ha mangiato?", "어디서 드셨어요?"),
(M, "Dietro l'angolo, dove andavo quando lavoravo qui vicino. La signora si ricordava di me. Mi ha detto che sono ingrassato.", "모퉁이 뒤에서요. 근처에서 일할 때 가던 데요. 사장님이 저를 기억하시더라고요. 살쪘다고 하셨어요."),
(K, "In Corea è un complimento. Vuol dire che a casa La trattano bene.", "한국에선 칭찬이에요. 집에서 잘 먹고 지낸다는 뜻이거든요."),
(M, "A casa ci sono le ribollite di mia madre. Leggiamo?", "집엔 어머니 리볼리타가 있죠. 읽어 볼까요?"),
(O, "Punto uno: esclusiva per la distribuzione nei grandi magazzini in tutta la Repubblica di Corea, durata due anni.", "1항. 대한민국 전역 백화점 유통 독점, 기간 2년."),
(M, "D'accordo.", "동의합니다."),
(O, "Punto due: il sito della società Corsini può vendere in Corea, al prezzo pubblico concordato, senza sconti né promozioni.", "2항. 코르시니사의 사이트는 합의된 소비자가로 한국에서 판매할 수 있으며, 할인이나 판촉은 하지 않는다."),
(M, "Aggiungiamo « salvo accordo scritto tra le parti ». Se un giorno vogliamo fare una promozione insieme, la facciamo insieme.", "'당사자 간 서면 합의가 있는 경우는 제외'를 넣죠. 언젠가 같이 판촉을 하고 싶으면 같이 하면 되니까요."),
(K, "Insieme mi piace. Scriva, Ye-jin.", "'같이'라는 말 좋네요. 적으세요, 예진 씨."),
(O, "Punto tre: nel caso in cui il sito violi il punto due, il grande magazzino può restituire l'invenduto al prezzo d'acquisto.", "3항. 사이트가 2항을 위반하는 경우, 백화점은 미판매분을 매입가로 반품할 수 있다."),
(M, "Va bene. È la mia proposta: la firmo volentieri.", "좋습니다. 제 제안이니 기꺼이 서명하죠."),
(O, "Signor Corsini, una domanda di traduzione: « invenduto » comprende anche le borse rovinate dai clienti?", "코르시니 씨, 번역 질문 하나요. '미판매분'에 손님이 망가뜨린 가방도 들어가나요?"),
(M, "No. L'invenduto è nuovo, con il cartellino. Le borse rovinate sono un'altra storia.", "아니요. 미판매분은 택이 달린 새 상품이에요. 망가진 가방은 다른 얘기죠."),
(O, "Punto quattro: minimo d'acquisto annuale. Lasciato in bianco.", "4항. 연간 최소 구매량. 공란."),
(K, "In bianco fino a giovedì della prossima settimana. Glielo ho detto.", "다음 주 목요일까지 공란이에요. 말씀드렸죠."),
(M, "E gli altri negozi? Quelli che non sono grandi magazzini, i concept store di Seongsu, per esempio?", "다른 매장은요? 백화점이 아닌 곳, 예를 들어 성수동 콘셉트 스토어들은요?"),
(K, "Lì ho una richiesta piccola. Prima di aprire con qualcuno in Corea, me lo dice. Non chiedo il permesso. Chiedo di saperlo per prima.", "그건 작은 부탁이 있어요. 한국에서 누구와 거래를 시작하기 전에 저한테 말해 주세요. 허락을 구하라는 게 아니라, 제가 먼저 알게 해 달라는 거예요."),
(M, "Diritto di essere informata per prima. Questo glielo do senza discutere.", "먼저 통보받을 권리. 그건 따질 것 없이 드리죠."),
(K, "Allora, Matteo, la cornice è fatta. Il contratto vero lo scrivono gli avvocati la settimana prossima. E lo firma chi può firmarlo.", "그럼 마테오 씨, 틀은 됐어요. 진짜 계약서는 다음 주에 변호사들이 써요. 그리고 서명할 수 있는 분이 서명하시고요."),
(M, "La mia procura arriva a cinquantamila euro. Un contratto di due anni, no. Lo firmerà mio fratello.", "제 위임장은 5만 유로까지예요. 2년짜리 계약은 안 돼요. 형이 서명할 거예요."),
(K, "Allora lo aspetto a Seul. (pausa) Matteo, non me ne voglia per stamattina. Ho chiesto tutto per sapere quanto potevo avere.", "그럼 서울에서 기다릴게요. (잠시) 마테오 씨, 오늘 아침 일은 언짢게 생각하지 마세요. 얼마나 얻을 수 있는지 알려고 전부 달라고 한 거예요."),
(M, "Non gliene voglio. A Seul l'ho imparato da Lei: si chiede tutto per arrivare al giusto.", "언짢지 않아요. 서울에서 김서연 씨한테 배웠잖아요. 적정선에 닿으려면 전부를 요구한다는 걸요."),
(K, "Allora ho una buona allieva. Cioè, un buon allievo. Vede? Anche io sono stanca.", "그럼 좋은 제자를 뒀네요. 아니, 남제자요. 보셨죠? 저도 피곤해요."),
(M, "Siamo pari, allora. Mercoledì vado a Tokyo con mia sorella.", "그럼 우리 비겼네요. 수요일엔 누나랑 도쿄에 가요."),
(K, "Lo so. Watanabe-san mi ha scritto ieri sera. (sorride) In Giappone, l'esclusiva non è mia. Ma i primi siete stati da me.", "알아요. 와타나베 씨가 어젯밤 연락하셨어요. (미소 지으며) 일본 독점은 제 게 아니죠. 그래도 처음은 저였어요."),
(M, "I primi saremo sempre stati da Lei.", "처음은 언제까지나 김서연 씨일 거예요."),
(K, "Questa frase la metto nel contratto.", "그 문장, 계약서에 넣을게요."),
(M, "Al punto cinque.", "5항에요."),
(K, "(ride) Al punto zero. Prima di tutti gli altri.", "(웃으며) 0항에요. 다른 모든 것보다 먼저."),

("#", "Scena 4 — Ore 21.30. Una camera d'albergo a Seul. A Scandicci sono le 14.30.", "장면 4 — 밤 9시 30분. 서울의 호텔 방. 스칸디치는 오후 2시 30분."),
(None, "Sul letto, il portatile aperto. Chiara è seduta accanto a Matteo, con i piedi sul letto e una scatola di gimbap. Sullo schermo, Filippo nel suo ufficio, con gli occhiali sulla fronte e la tabella delle vendite di aprile davanti.", "침대 위에 노트북이 열려 있다. 키아라는 발을 침대에 올리고 김밥 한 상자를 든 채 마테오 옆에 앉아 있다. 화면 속 필리포는 사무실에 앉아 이마에 안경을 걸치고 4월 판매표를 앞에 두고 있다."),
(F, "Allora. Mi dite tutto o mi dite le cose belle?", "자. 전부 말할 거야, 좋은 것만 말할 거야?"),
(M, "Ti dico tutto. Cominciando dalla cosa che non ti piacerà.", "전부 말할게. 형이 싫어할 것부터."),
(F, "Bravo. Così poi le cose belle me le gusto.", "잘했어. 그래야 좋은 걸 나중에 맛있게 듣지."),
(M, "Kim voleva l'esclusiva per tutta la Corea, tre anni, tutti i canali, e il nostro sito chiuso in Corea.", "김서연 씨는 한국 전역 독점, 3년, 모든 채널, 그리고 한국에서 우리 사이트 폐쇄를 원했어."),
(F, "E tu?", "그래서 넌?"),
(M, "Io le ho detto di no sul sito. Le ho detto di sì sui grandi magazzini di tutta la Corea, per due anni. Il sito resta aperto, allo stesso prezzo, senza sconti. Se un giorno facciamo uno sconto, lei può restituirci l'invenduto.", "사이트는 안 된다고 했어. 한국 모든 백화점은 된다고 했고, 2년. 사이트는 같은 가격, 할인 없이 유지. 언젠가 우리가 할인하면 그쪽이 미판매분을 반품할 수 있어."),
(F, "(si toglie gli occhiali) Hai deciso tu, da solo, due anni di esclusiva?", "(안경을 벗으며) 2년 독점을 너 혼자 정했다고?"),
(M, "Ho deciso una cornice. Il contratto vero no. Quello lo scrivono gli avvocati e lo firmi tu. A Seul.", "틀을 정했어. 진짜 계약은 아니야. 그건 변호사들이 쓰고 형이 서명해. 서울에서."),
(F, "A Seul. Io.", "서울에서. 내가."),
(C, "(con la bocca piena) Ti ho detto di prenotare, a marzo. Non mi hai ascoltato.", "(입에 음식을 문 채) 3월에 예약하라고 했잖아. 내 말 안 들었지."),
(F, "Chiara, mangia. E il minimo d'acquisto?", "키아라, 먹어. 최소 구매량은?"),
(M, "In bianco fino a giovedì prossimo. Lo scrive lei, dopo aver visto le vendite della seconda settimana. Dice che le serve per ottenere il budget dal suo direttore.", "다음 주 목요일까지 공란이야. 둘째 주 판매를 보고 그쪽이 적는대. 부장한테 예산 받으려면 필요하대."),
(F, "Uno che chiede di scrivere un minimo da sola. Questa non l'ho mai vista in vent'anni di Maison.", "최소 구매량을 자기가 적겠다는 사람이라. 메종하고 20년 일하면서 그런 건 못 봤어."),
(C, "Perché la Maison i minimi li scriveva per noi. Al contrario.", "메종은 늘 우리한테 최소량을 정해 줬으니까. 반대로."),
(F, "(un silenzio) E le vendite?", "(잠시 침묵) 판매는?"),
(M, "Ventitré in quattro giorni. Crema esaurita. Sette ordinazioni per la Collina. Watanabe ha comprato una Torri per sé.", "나흘에 23개. 크림색 품절. '라 콜리나' 주문 일곱 건. 와타나베 씨는 자기용으로 '토리'를 하나 샀고."),
(C, "E la signora Yoon ha comprato l'ultima crema « per Tiziana ». Diglielo, a Tiziana.", "그리고 윤 여사님은 마지막 크림색을 '티치아나를 위해서' 샀어. 티치아나한테 꼭 전해 줘."),
(M, "E Ji-hoon ha imparato « ogni borsa ha il nome di chi l'ha cucita ». Sua madre cuce hanbok a Daegu.", "그리고 지훈 씨가 '모든 가방에는 꿰맨 사람의 이름이 있다'를 외웠어. 어머니가 대구에서 한복을 지으신대."),
(F, "Fine aprile è mercoledì. Il trenta. Vi avevo detto che a fine aprile decidevo se congelare il budget.", "4월 말이 수요일이야. 30일. 4월 말에 예산 동결 여부를 정한다고 했지."),
(M, "Lo so. E il trenta io e Chiara siamo a Tokyo.", "알아. 그리고 30일에 나랑 누나는 도쿄에 있어."),
(F, "Allora ve lo dico a Seul. Di persona. Non per telefono.", "그럼 서울에서 말해 줄게. 직접. 전화로 말고."),
(C, "Filippo, ma è un sì o un no?", "필리포, 그래서 된다는 거야, 안 된다는 거야?"),
(F, "È un « vengo a vedere ». Prenoto il volo per il dieci. Così firmo anche, se c'è da firmare.", "'보러 간다'야. 10일 비행기 예약할게. 서명할 게 있으면 그때 하고."),
(M, "C'è da firmare.", "서명할 거 있어."),
(F, "Allora porto la penna di babbo. E Matteo...", "그럼 아빠 펜 가져갈게. 그리고 마테오…"),
(M, "Sì?", "응?"),
(F, "Il sito l'hai difeso bene. Babbo avrebbe chiuso tutto, pur di firmare. Tu no.", "사이트는 잘 지켰어. 아빠였으면 서명하려고 다 닫았을 거야. 넌 안 그랬지."),
(None, "Filippo chiude la chiamata prima che qualcuno possa rispondere. Chiara guarda lo schermo nero, poi il fratello.", "누가 대답하기도 전에 필리포가 통화를 끊는다. 키아라는 꺼진 화면을 보다가 동생을 본다."),
(C, "Hai sentito? Ti ha fatto un complimento.", "들었어? 너 칭찬했어."),
(M, "Non ha detto che è un complimento.", "칭찬이라고는 안 했어."),
(C, "(gli passa un gimbap) Mangia. Mercoledì c'è Tokyo, e io in aereo vomito.", "(김밥을 하나 건네며) 먹어. 수요일엔 도쿄 가야 하고, 난 비행기에서 토하잖아."),
(M, "Due ore e mezza. Porta lo zenzero.", "두 시간 반이야. 생강 챙겨."),
(C, "E tu porta i biglietti da visita. Da dare con due mani.", "그리고 넌 명함 챙겨. 두 손으로 줄 거."),
(M, "Centonovantasei. Uno l'ho dato a Ye-jin.", "196장. 한 장은 예진 씨한테 줬어."),
]

